"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["74259"],{67556(e){e.exports=JSON.parse('{"id":"V4-078","slug":"say-on-pay","term":"Say on Pay","also_known_as":[],"difficulty":"Intermediate","definition":"Say on pay is the right of a company\u2019s shareholders to vote on the pay of its senior executives, either on the overall pay policy, the pay actually awarded, or both.","explanation":["Say on pay was introduced to increase accountability for executive pay, which has often been criticised as too high or poorly linked to performance.","The rules differ between countries. In the United Kingdom, shareholders of listed companies have an annual advisory vote on the remuneration report and a binding vote on the remuneration policy at least every three years. In the United States, the Dodd-Frank Act of 2010 introduced advisory say-on-pay votes for public companies. Many European countries have similar rules under European Union law.","For example, if a large share of shareholders vote against a company\u2019s pay report, the board is expected to engage with investors and explain how it will respond, even if the vote is only advisory.","Although advisory votes are not binding, significant opposition can embarrass boards, lead to changes in pay arrangements and influence the re-election of remuneration committee members. Proxy advisory firms, which advise institutional investors on how to vote, play an important role in say-on-pay votes."],"note":"","total":1725,"prev":{"slug":"savings-bank","term":"Savings Bank"},"next":{"slug":"scalability","term":"Scalability"}}')}}]);